CREATE DATABASE Vista_Atlantico;
USE Vista_Atlantico;

CREATE TABLE PROPRIETARIO (
    ID_PROPRIETARIO INT,
    Nome VARCHAR(100),
    Telefone VARCHAR(20),
    Email VARCHAR(100)
);

CREATE TABLE CLIENTE (
    ID_CLIENTE INT,
    Nome VARCHAR(100),
    Telefone VARCHAR(20),
    Email VARCHAR(100)
);

CREATE TABLE CORRETOR (
    ID_CORRETOR INT,
    CRECI VARCHAR(15),
    Nome VARCHAR(100),
    Telefone VARCHAR(20),
    Status_Corretor VARCHAR(30),
    Email VARCHAR(100)
);

CREATE TABLE IMOVEL (
    ID_IMOVEL CHAR(11),
    QTDE_quartos INT,
    QTDE_banheiros INT,
    Tipo_Imovel VARCHAR(30),
    QTDE_vagas_garagem INT,
    Area_M2 DECIMAL(8,2),
    Valor_Imovel DECIMAL(12,2),
    Finalidade VARCHAR(30),
    Tipo_Oferta VARCHAR(30),
    IPTU DECIMAL(10,2),
    Status_Imovel VARCHAR(30),
    Numero VARCHAR(10),
    Logradouro VARCHAR(150),
    Bairro VARCHAR(80),
    Complemento VARCHAR(100),
    Cidade VARCHAR(80),
    CEP CHAR(9)
);

CREATE TABLE Fotos_Imovel (
    ID_FOTO INT,
    Caminho_Foto VARCHAR(255),
    ID_IMOVEL CHAR(11)
);

CREATE TABLE CONTRATO (
    ID_CONTRATO CHAR(10),
    ID_IMOVEL CHAR(11),
    Data_Inicio DATE,
    Data_Fim DATE,
    Tipo_Contrato VARCHAR(30),
    Valor_Contrato DECIMAL(12,2),
    Forma_Pagamento VARCHAR(30)
);

CREATE TABLE VISITA (
    ID_VISITA VARCHAR(9),
    ID_IMOVEL CHAR(11),
    Data_Horario_Visita DATETIME,
    Anotacao_Visita VARCHAR(500)
);

CREATE TABLE Idioma (
    Idioma VARCHAR(30),
    ID_CORRETOR INT
);

CREATE TABLE ENCOMENDA (
    ID_ENCOMENDA INT,
    ID_CLIENTE INT,
    Valor_Minimo DECIMAL(12,2),
    Cidade_Desejada VARCHAR(80),
    Bairro_Desejado VARCHAR(80),
    Valor_Maximo DECIMAL(12,2),
    Data_Encomenda DATE,
    Desc_Imovel VARCHAR(500),
    Status_Enc VARCHAR(30)
);

CREATE TABLE DOCUMENTO (
    ID_DOC VARCHAR(10),
    Nome_Doc VARCHAR(30),
    Data_Doc DATE,
    Tipo_Doc VARCHAR(30)
);

-- =====================================================
-- Tabelas de relacionamento (N:N)
-- =====================================================

CREATE TABLE POSSUI (
    ID_IMOVEL CHAR(11),
    ID_PROPRIETARIO INT
);

CREATE TABLE AGENDA (
    ID_VISITA VARCHAR(9),
    ID_CLIENTE INT
);

CREATE TABLE REALIZA (
    ID_VISITA VARCHAR(9),
    ID_CORRETOR INT
);

CREATE TABLE ASSINA (
    ID_CONTRATO CHAR(11),
    ID_CLIENTE INT
);

CREATE TABLE INTERMEDIA (
    ID_CORRETOR INT,
    ID_CONTRATO CHAR(11)
);

CREATE TABLE REGISTRA (
    ID_DOC VARCHAR(10),
    ID_CORRETOR INT
);


