/* =====================================================================
   2. SELECT COM JOIN
   ===================================================================== */

-- S01 — Quais contratos existem, com imóvel, cliente signatário e corretor?
SELECT c.ID_CONTRATO, c.Data_Inicio, c.Tipo_Contrato, c.Valor_Contrato,
       i.Tipo_Imovel, i.Bairro,
       cl.Nome AS cliente, co.Nome AS corretor
FROM CONTRATO c
JOIN IMOVEL i          ON i.ID_IMOVEL = c.ID_IMOVEL
LEFT JOIN ASSINA a     ON a.ID_CONTRATO = c.ID_CONTRATO
LEFT JOIN CLIENTE cl   ON cl.ID_CLIENTE = a.ID_CLIENTE
LEFT JOIN INTERMEDIA im ON im.ID_CONTRATO = c.ID_CONTRATO
LEFT JOIN CORRETOR co  ON co.ID_CORRETOR = im.ID_CORRETOR
ORDER BY c.ID_CONTRATO;

-- S02 — Quais visitas foram agendadas, para qual imóvel, cliente e corretor?
SELECT v.ID_VISITA, v.Data_Horario_Visita, i.Tipo_Imovel, i.Bairro,
       cl.Nome AS cliente, co.Nome AS corretor
FROM VISITA v
JOIN IMOVEL i          ON i.ID_IMOVEL = v.ID_IMOVEL
LEFT JOIN AGENDA ag    ON ag.ID_VISITA = v.ID_VISITA
LEFT JOIN CLIENTE cl   ON cl.ID_CLIENTE = ag.ID_CLIENTE
LEFT JOIN REALIZA r    ON r.ID_VISITA = v.ID_VISITA
LEFT JOIN CORRETOR co  ON co.ID_CORRETOR = r.ID_CORRETOR
ORDER BY v.Data_Horario_Visita;

-- S03 — Quem são os proprietários de cada imóvel?
SELECT i.ID_IMOVEL, i.Tipo_Imovel, i.Bairro, p.Nome AS proprietario, p.Telefone
FROM IMOVEL i
JOIN POSSUI po       ON po.ID_IMOVEL = i.ID_IMOVEL
JOIN PROPRIETARIO p  ON p.ID_PROPRIETARIO = po.ID_PROPRIETARIO
ORDER BY i.ID_IMOVEL, p.Nome;

-- S04 — Quais fotos estão cadastradas para cada imóvel?
SELECT i.ID_IMOVEL, i.Tipo_Imovel, f.ID_FOTO, f.Caminho_Foto
FROM IMOVEL i
JOIN Fotos_Imovel f ON f.ID_IMOVEL = i.ID_IMOVEL
ORDER BY i.ID_IMOVEL, f.ID_FOTO;

-- S05 — Quais encomendas os clientes fizeram e com que status?
SELECT e.ID_ENCOMENDA, cl.Nome AS cliente, e.Cidade_Desejada, e.Bairro_Desejado,
       e.Valor_Minimo, e.Valor_Maximo, e.Data_Encomenda, e.Status_Enc
FROM ENCOMENDA e
JOIN CLIENTE cl ON cl.ID_CLIENTE = e.ID_CLIENTE
ORDER BY e.Data_Encomenda;

-- S06 — Quais idiomas cada corretor atende?
SELECT co.ID_CORRETOR, co.Nome, co.CRECI, co.Status_Corretor,
       GROUP_CONCAT(id.Idioma ORDER BY id.Idioma SEPARATOR ', ') AS idiomas
FROM CORRETOR co
LEFT JOIN Idioma id ON id.ID_CORRETOR = co.ID_CORRETOR
GROUP BY co.ID_CORRETOR, co.Nome, co.CRECI, co.Status_Corretor;

