-- D1 — Remove a visita cancelada (primeiro as tabelas filhas, depois a visita)
DELETE FROM AGENDA
WHERE ID_VISITA IN (SELECT ID_VISITA FROM VISITA WHERE Anotacao_Visita LIKE 'CANCELADA%');

DELETE FROM REALIZA
WHERE ID_VISITA IN (SELECT ID_VISITA FROM VISITA WHERE Anotacao_Visita LIKE 'CANCELADA%');

DELETE FROM VISITA
WHERE ID_VISITA = 'VIS-1040';

