WHERE ID_ENCOMENDA = 50005
  AND Status_Enc = 'CANCELADA';
  
  /* =====================================================================
   5. CONSULTAS GERENCIAIS
   Obs.: troque o texto "Atende" pelos códigos P/KPI da seção 1.6.
   ===================================================================== */

-- G01 — Qual o faturamento (valor contratado) por mês e por tipo de contrato?
-- Atende: KPI de faturamento por período (em Locação, o valor é a mensalidade)
SELECT DATE_FORMAT(c.Data_Inicio, '%Y-%m') AS mes,
       c.Tipo_Contrato,
       COUNT(*)                          AS qtd_contratos,
       SUM(c.Valor_Contrato)             AS valor_total,
       ROUND(AVG(c.Valor_Contrato), 2)   AS ticket_medio
FROM CONTRATO c
GROUP BY DATE_FORMAT(c.Data_Inicio, '%Y-%m'), c.Tipo_Contrato
ORDER BY mes, c.Tipo_Contrato;

-- G02 — Quais corretores mais fecham contratos e realizam visitas?
-- Atende: KPI de produtividade por corretor (subconsultas evitam duplicar contagens)
SELECT co.ID_CORRETOR, co.Nome, co.Status_Corretor,
       COALESCE(ct.qtd_contratos, 0) AS qtd_contratos,
       COALESCE(ct.valor_total, 0)   AS valor_total,
       COALESCE(vs.qtd_visitas, 0)   AS qtd_visitas
FROM CORRETOR co
LEFT JOIN (SELECT im.ID_CORRETOR, COUNT(*) AS qtd_contratos, SUM(c.Valor_Contrato) AS valor_total
           FROM INTERMEDIA im
           JOIN CONTRATO c ON c.ID_CONTRATO = im.ID_CONTRATO
           GROUP BY im.ID_CORRETOR) ct ON ct.ID_CORRETOR = co.ID_CORRETOR
LEFT JOIN (SELECT ID_CORRETOR, COUNT(*) AS qtd_visitas
           FROM REALIZA
           GROUP BY ID_CORRETOR) vs ON vs.ID_CORRETOR = co.ID_CORRETOR
ORDER BY valor_total DESC, qtd_visitas DESC;

-- G03 — Qual percentual das visitas termina em contrato?
-- Atende: KPI de taxa de conversão de visitas (convertida = cliente da visita assina contrato do mesmo imóvel na data da visita ou depois)
WITH visitas AS (
    SELECT v.ID_VISITA,
           CASE 
               WHEN EXISTS (
                   SELECT 1
                   FROM AGENDA ag
                   JOIN ASSINA s   ON s.ID_CLIENTE = ag.ID_CLIENTE
                   JOIN CONTRATO c ON c.ID_CONTRATO = s.ID_CONTRATO
                   WHERE ag.ID_VISITA = v.ID_VISITA
                     AND c.ID_IMOVEL = v.ID_IMOVEL
                     AND c.Data_Inicio >= DATE(v.Data_Horario_Visita)
               ) THEN 1 
               ELSE 0 
           END AS convertida
    FROM VISITA v
)
SELECT COUNT(*) AS total_visitas,
       COALESCE(SUM(convertida), 0) AS visitas_convertidas,
       ROUND(100.0 * COALESCE(SUM(convertida), 0) / NULLIF(COUNT(*), 0), 2) AS taxa_conversao_pct
FROM visitas;

-- G04 — Quantos contratos são fechados sem visita prévia do cliente ao imóvel?
-- Atende: KPI de negócios sem visita (o cliente pode comprar ou alugar sem visitar)
WITH visitas AS (
    SELECT v.ID_VISITA,
           CASE 
               WHEN EXISTS (
                   SELECT 1
                   FROM AGENDA ag
                   JOIN ASSINA s   ON s.ID_CLIENTE = ag.ID_CLIENTE
                   JOIN CONTRATO c ON c.ID_CONTRATO = s.ID_CONTRATO
                   WHERE ag.ID_VISITA = v.ID_VISITA
                     AND c.ID_IMOVEL = v.ID_IMOVEL
               ) THEN 1 
               ELSE 0 
           END AS convertida
    FROM VISITA v
)
SELECT COUNT(*) AS total_visitas,
       COALESCE(SUM(convertida), 0) AS visitas_convertidas,
       ROUND(100.0 * COALESCE(SUM(convertida), 0) / NULLIF(COUNT(*), 0), 2) AS taxa_conversao_pct
FROM visitas;


-- G05 — Quais imóveis disponíveis estão parados, sem nenhum contrato?
-- Atende: problema de imóveis sem giro (sem data de cadastro, usa-se a 1ª visita como referência)
SELECT i.ID_IMOVEL, i.Tipo_Imovel, i.Tipo_Oferta, i.Bairro, i.Valor_Imovel,
       COUNT(v.ID_VISITA)                                    AS qtd_visitas,
       MIN(v.Data_Horario_Visita)                            AS primeira_visita,
       DATEDIFF(CURDATE(), MIN(v.Data_Horario_Visita))       AS dias_desde_primeira_visita
FROM IMOVEL i
LEFT JOIN VISITA v ON v.ID_IMOVEL = i.ID_IMOVEL
WHERE i.Status_Imovel = 'DISPONIVEL'
  AND NOT EXISTS (SELECT 1 FROM CONTRATO c WHERE c.ID_IMOVEL = i.ID_IMOVEL)
GROUP BY i.ID_IMOVEL, i.Tipo_Imovel, i.Tipo_Oferta, i.Bairro, i.Valor_Imovel
ORDER BY dias_desde_primeira_visita DESC, qtd_visitas ASC;

-- G06 — Quais bairros têm mais encomendas e há imóvel disponível compatível com a faixa de valor?
-- Atende: problema de demanda não atendida
SELECT e.Cidade_Desejada, e.Bairro_Desejado,
       COUNT(*)                          AS qtd_encomendas,
       ROUND(AVG(e.Valor_Minimo), 2)     AS valor_minimo_medio,
       ROUND(AVG(e.Valor_Maximo), 2)     AS valor_maximo_medio,
       SUM(EXISTS (SELECT 1
                   FROM IMOVEL i
                   WHERE i.Cidade = e.Cidade_Desejada
                     AND i.Bairro = e.Bairro_Desejado
                     AND i.Status_Imovel = 'DISPONIVEL'
                     AND i.Valor_Imovel BETWEEN COALESCE(e.Valor_Minimo, 0)
                                            AND COALESCE(e.Valor_Maximo, 999999999999.99))) AS encomendas_com_oferta_compativel
FROM ENCOMENDA e
GROUP BY e.Cidade_Desejada, e.Bairro_Desejado
ORDER BY qtd_encomendas DESC;

-- G07 — Quais bairros e tipos de imóvel concentram mais visitas, contratos e valor?
-- Atende: KPI de desempenho por localização/tipo (agregações em subconsultas para não duplicar valores)
SELECT i.Bairro, i.Tipo_Imovel,
       COUNT(*)                                   AS qtd_imoveis,
       COALESCE(SUM(vis.qtd_visitas), 0)          AS qtd_visitas,
       COALESCE(SUM(con.qtd_contratos), 0)        AS qtd_contratos,
       ROUND(AVG(i.Valor_Imovel), 2)              AS valor_medio_anunciado,
       ROUND(SUM(con.valor_contratos) / NULLIF(SUM(con.qtd_contratos), 0), 2) AS valor_medio_contrato
FROM IMOVEL i
LEFT JOIN (SELECT ID_IMOVEL, COUNT(*) AS qtd_visitas
           FROM VISITA GROUP BY ID_IMOVEL) vis ON vis.ID_IMOVEL = i.ID_IMOVEL
LEFT JOIN (SELECT ID_IMOVEL, COUNT(*) AS qtd_contratos, SUM(Valor_Contrato) AS valor_contratos
           FROM CONTRATO GROUP BY ID_IMOVEL) con ON con.ID_IMOVEL = i.ID_IMOVEL
GROUP BY i.Bairro, i.Tipo_Imovel
ORDER BY qtd_contratos DESC, qtd_visitas DESC;

-- G08 — Quantas encomendas estão abertas, atendidas ou canceladas?
-- Atende: KPI de taxa de atendimento das encomendas
SELECT e.Status_Enc,
       COUNT(*) AS qtd_encomendas,
       ROUND(100 * COUNT(*) / (SELECT COUNT(*) FROM ENCOMENDA), 2) AS pct_do_total
FROM ENCOMENDA e
GROUP BY e.Status_Enc
ORDER BY qtd_encomendas DESC;

-- G09 — Quantas visitas e imóveis visitados existem por mês?
-- Atende: KPI de volume de atendimentos
SELECT DATE_FORMAT(v.Data_Horario_Visita, '%Y-%m') AS mes,
       COUNT(*)                   AS qtd_visitas,
       COUNT(DISTINCT v.ID_IMOVEL) AS imoveis_visitados
FROM VISITA v
GROUP BY DATE_FORMAT(v.Data_Horario_Visita, '%Y-%m')
ORDER BY mes;

-- G10 — Qual a carteira de imóveis por situação e tipo de oferta, com valor total?
-- Atende: KPI de estoque (carteira) de imóveis
SELECT i.Status_Imovel, i.Tipo_Oferta,
       COUNT(*)                     AS qtd_imoveis,
       SUM(i.Valor_Imovel)          AS valor_total,
       ROUND(AVG(i.Area_M2), 2)     AS area_media_m2
FROM IMOVEL i
GROUP BY i.Status_Imovel, i.Tipo_Oferta
ORDER BY i.Status_Imovel, i.Tipo_Oferta;

/* =====================================================================
   6. CONSULTAS DE AUDITORIA
   Códigos: RN01..RN13 = regras de negócio | RL01..RL03 = restrições legais
   RN01  Maioridade                         RN08  Visita: imóvel, cliente e corretor
   RN02  Imóvel disponível para oferta      RN09  Corretor sem visitas conflitantes
   RN03  Cliente cadastrado                 RN10  Contrato: imóvel, cliente e corretor
   RN04  Comprovante de renda               RN11  Disponibilidade atualizada
   RN05  Imóvel com imagens de qualidade    RN12  CRECI ativo e situação regular
   RN06  Imóvel com ao menos 1 proprietário RN13  Compra/Locação sem visita permitido
   RN07  Contratos sem negociação incompatível
   RL01  LGPD | RL02  CRECI nos contratos | RL03  Lei do Inquilinato (8.245/91)
   Não auditáveis com este modelo: RN01 (sem data de nascimento),
   RN04 (sem comprovante de renda) e RL01 (sem campos de documentos/criptografia).
   ===================================================================== */

-- A01 — Existe contrato sem nenhum cliente signatário?
-- Verifica: RN03 e RN10 (todo contrato tem ao menos um cliente cadastrado)
SELECT c.ID_CONTRATO, c.ID_IMOVEL, c.Tipo_Contrato, c.Data_Inicio, c.Valor_Contrato
FROM CONTRATO c
WHERE NOT EXISTS (SELECT 1 FROM ASSINA a WHERE a.ID_CONTRATO = c.ID_CONTRATO);

-- A02 — Existe contrato sem corretor responsável pela intermediação?
-- Verifica: RN10 e RL02 (todo contrato registra o corretor responsável)
SELECT c.ID_CONTRATO, c.ID_IMOVEL, c.Tipo_Contrato, c.Data_Inicio, c.Valor_Contrato
FROM CONTRATO c
WHERE NOT EXISTS (SELECT 1 FROM INTERMEDIA im WHERE im.ID_CONTRATO = c.ID_CONTRATO);

-- A03 — Existe visita sem cliente interessado ou sem corretor responsável?
-- Verifica: RN08 (visita vinculada a imóvel, cliente e corretor)
SELECT v.ID_VISITA, v.ID_IMOVEL, v.Data_Horario_Visita,
       (SELECT COUNT(*) FROM AGENDA ag WHERE ag.ID_VISITA = v.ID_VISITA) AS qtd_clientes,
       (SELECT COUNT(*) FROM REALIZA r  WHERE r.ID_VISITA = v.ID_VISITA) AS qtd_corretores
FROM VISITA v
WHERE NOT EXISTS (SELECT 1 FROM AGENDA ag WHERE ag.ID_VISITA = v.ID_VISITA)
   OR NOT EXISTS (SELECT 1 FROM REALIZA r  WHERE r.ID_VISITA = v.ID_VISITA);

-- A04 — Existe visita marcada depois de o imóvel já ter sido negociado?
-- Verifica: RN02 (imóvel só é oferecido se estiver disponível). Sem Data_Fim, todo contrato é tratado como vigente.
SELECT v.ID_VISITA, v.ID_IMOVEL, v.Data_Horario_Visita,
       c.ID_CONTRATO, c.Tipo_Contrato, c.Data_Inicio, c.Data_Fim
FROM VISITA v
JOIN CONTRATO c ON c.ID_IMOVEL = v.ID_IMOVEL
               AND DATE(v.Data_Horario_Visita) > c.Data_Inicio
               AND (c.Data_Fim IS NULL OR DATE(v.Data_Horario_Visita) <= c.Data_Fim)
ORDER BY v.ID_IMOVEL, v.Data_Horario_Visita;

-- A05 — Existe imóvel cadastrado sem nenhum proprietário?
-- Verifica: RN06 (todo imóvel tem ao menos um proprietário; vários são permitidos)
SELECT i.ID_IMOVEL, i.Tipo_Imovel, i.Bairro, i.Status_Imovel
FROM IMOVEL i
LEFT JOIN POSSUI po ON po.ID_IMOVEL = i.ID_IMOVEL
WHERE po.ID_PROPRIETARIO IS NULL;

-- A06 — Existe contrato intermediado por corretor demitido, excluído ou com CRECI inválido?
-- Verifica: RN12 e RL02 (transação só com corretor de CRECI ativo e situação regular)
SELECT c.ID_CONTRATO, c.Data_Inicio, co.ID_CORRETOR, co.Nome, co.CRECI, co.Status_Corretor
FROM CONTRATO c
JOIN INTERMEDIA im ON im.ID_CONTRATO = c.ID_CONTRATO
JOIN CORRETOR co   ON co.ID_CORRETOR = im.ID_CORRETOR
WHERE LOWER(co.Status_Corretor) NOT IN ('ativo', 'ativa', 'Férias', 'Afastado');

-- A07 — Existe corretor com visitas em horários conflitantes (menos de 60 minutos entre elas)?
-- Verifica: RN09 (a visita não tem horário de término; a janela de 60 min é uma premissa)
SELECT co.ID_CORRETOR, co.Nome,
       v1.ID_VISITA AS visita_a, v1.Data_Horario_Visita AS horario_a,
       v2.ID_VISITA AS visita_b, v2.Data_Horario_Visita AS horario_b
FROM REALIZA r1
JOIN REALIZA r2   ON r2.ID_CORRETOR = r1.ID_CORRETOR AND r2.ID_VISITA > r1.ID_VISITA
JOIN VISITA v1    ON v1.ID_VISITA = r1.ID_VISITA
JOIN VISITA v2    ON v2.ID_VISITA = r2.ID_VISITA
JOIN CORRETOR co  ON co.ID_CORRETOR = r1.ID_CORRETOR
WHERE ABS(TIMESTAMPDIFF(MINUTE, v1.Data_Horario_Visita, v2.Data_Horario_Visita)) < 60;

-- A08 — Existe contrato de Locação sem locatário, sem corretor ou sem forma de pagamento?
-- Verifica: RL03 (Lei 8.245/91; o modelo não guarda prazo nem garantia, então só se valida o que existe)
SELECT c.ID_CONTRATO, c.ID_IMOVEL, c.Data_Inicio, c.Valor_Contrato, c.Forma_Pagamento,
       (SELECT COUNT(*) FROM ASSINA a      WHERE a.ID_CONTRATO = c.ID_CONTRATO)  AS qtd_locatarios,
       (SELECT COUNT(*) FROM INTERMEDIA im WHERE im.ID_CONTRATO = c.ID_CONTRATO) AS qtd_corretores
FROM CONTRATO c
WHERE c.Tipo_Contrato = 'Locação'
  AND (NOT EXISTS (SELECT 1 FROM ASSINA a      WHERE a.ID_CONTRATO = c.ID_CONTRATO)
    OR NOT EXISTS (SELECT 1 FROM INTERMEDIA im WHERE im.ID_CONTRATO = c.ID_CONTRATO)
    OR TRIM(c.Forma_Pagamento) = '');
